def transform(grid):
    out = [row[:] for row in grid]
    # Locate a long horizontal bar whose right end is truncated; color its
    # remaining suffix as the marker color used by the task.
    for row in out:
        color = max(set(row), key=row.count)
        if row[0] == color:
            end = 0
            while end < len(row) and row[end] == color:
                end += 1
            if 0 < end < len(row) and all(v != color for v in row[end:]):
                # The incomplete repeated bar is distinguished from an intact
                # bar by the background suffix.
                if end >= len(row) // 2:
                    row[end:] = [1] * (len(row) - end)
    return out

